import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify potential drivers using t-statistics and correlation filtering
    drivers = []
    seen = set()

    # Filter features by significance (p < 0.1) and effect size
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'expression':
            t_stat = feats.x[:, i].std() * (feats.x[feats.y==1, i].mean() - feats.x[feats.y==0, i].mean()) / (feats.x[:, i].std() + 1e-8)
            if abs(t_stat) > 1.5:
                drivers.append((abs(t_stat), fid))

    # Sort by t-statistic magnitude
    drivers.sort(reverse=True)
    drivers = [fid for _, fid in drivers[:MAX_DRIVERS]]

    # Remove near-duplicates based on correlations
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                if fid1 in drivers and fid2 in drivers:
                    correlated_pairs.add((min(fid1, fid2), max(fid1, fid2)))

    # Keep only one from each correlated pair
    filtered_drivers = []
    for d in drivers:
        is_correlated = any(d in pair for pair in correlated_pairs)
        if not is_correlated or d not in seen:
            filtered_drivers.append(d)
            seen.add(d)
            if len(filtered_drivers) >= MAX_DRIVERS:
                break

    drivers = filtered_drivers

    # Build columns and products
    columns = list(drivers)
    products = []

    # Add interaction terms between top drivers
    for i in range(len(drivers)):
        for j in range(i+1, len(drivers)):
            products.append((drivers[i], drivers[j]))

    # Weighted score: simple sum of top drivers
    loadings = {fid: 1.0 for fid in drivers}

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

